query ProductSnapshot($id: ID!) {
  product(id: $id) {
    id title handle status vendor productType createdAt updatedAt publishedAt descriptionHtml tags onlineStoreUrl onlineStorePreviewUrl templateSuffix
    seo { title description }
    options { id name position optionValues { id name } }
    featuredMedia { id }
    variants(first: 50) { nodes { id title position price compareAtPrice sku barcode taxable inventoryPolicy inventoryQuantity selectedOptions { name value } inventoryItem { id tracked } } pageInfo { hasNextPage endCursor } }
    metafields(first: 50) { nodes { id namespace key type value } pageInfo { hasNextPage endCursor } }
    metafieldsCustom: metafields(first: 50, namespace: "custom") { nodes { id namespace key type value } pageInfo { hasNextPage endCursor } }
    resourcePublicationsV2(first: 20) { nodes { isPublished publishDate publication { id name } } pageInfo { hasNextPage endCursor } }
    unpublishedPublications(first: 20) { nodes { id name } pageInfo { hasNextPage endCursor } }
    collections(first: 20) { nodes { id handle title } pageInfo { hasNextPage endCursor } }
    media(first: 20) { nodes { id mediaContentType alt ... on MediaImage { image { url width height } } } pageInfo { hasNextPage endCursor } }
  }
}

queries.graphql:
query Menus($first: Int!, $after: String) {
  menus(first: $first, after: $after) {
    nodes {
      id handle title isDefault
      items {
        id title type url resourceId tags
        items {
          id title type url resourceId tags
          items { id title type url resourceId tags }
        }
      }
    }
    pageInfo { hasNextPage endCursor }
  }
}

query Collections($first: Int!, $after: String) {
  collections(first: $first, after: $after) {
    nodes {
      id handle title updatedAt sortOrder
      productsCount { count precision }
      descriptionHtml
      seo { title description }
      ruleSet { appliedDisjunctively rules { column relation condition } }
      products(first: 100, sortKey: COLLECTION_DEFAULT) {
        nodes { id handle title status }
        pageInfo { hasNextPage endCursor }
      }
    }
    pageInfo { hasNextPage endCursor }
  }
}

query CollectionProducts($id: ID!, $after: String) {
  collection(id: $id) {
    id handle
    products(first: 100, after: $after, sortKey: COLLECTION_DEFAULT) {
      nodes { id handle title status }
      pageInfo { hasNextPage endCursor }
    }
  }
}
